Given two arrays a[] and b[], and a positive integer x, find a pair (a[i], b[j]) such that the sum of a[i] and b[j] is closest to x, in other words the absolute difference |a[i] + b[j] - x| is minimized.Example: Input:  a[] = [1, 4, 5, 7], b[] = [10, 20, 30, 40], x = 32Output:  [1, 30]Explanation: The pair (1, 30) gives sum 31, which is closest to 32 (minimum difference = 1).Input:  a[] = [1, 4, 5, 7], b[] = [10, 20, 30, 40], x = 50      Output:  [7, 40]Explanation: The pair (7, 40) gives sum 47, which is closest to 50 (minimum difference = 3).Try It YourselfTable of Content[Naive Approach] Using Nested Loops - O(n × m) Time and O(1) Space[Expected Approach] - Using Two Pointer - O(n + m) Time and O(1) Space[Naive Approach] Using Nested Loops - O(n × m) Time and O(1) SpaceA naive approach is to check all possible pairs formed by taking one element from a[] and one from b[]. For each pair we  compute the value |a[i] + b[j] − x| and keep track of the pair that gives the minimum difference.
            C++

    #include <iostream>
#include <vector>
#include <climits>
#include <cmath>
using namespace std;

// Function to find the closest pair
pair<int, int> closestPair(vector<int>& a, vector<int>& b, int x) {
    int minDiff = INT_MAX;
    pair<int, int> res;

    // Traverse all pairs
    for (int i = 0; i < a.size(); i++) {
        for (int j = 0; j < b.size(); j++) {
            int diff = abs(a[i] + b[j] - x);

            if (diff < minDiff) {
                minDiff = diff;
                res = {a[i], b[j]};
            }
        }
    }

    return res;
}

int main() {
    vector<int> a = {1, 4, 5, 7};
    vector<int> b = {10, 20, 30, 40};
    int x = 50;

    pair<int, int> ans = closestPair(a, b, x);
    cout << "[" << ans.first << ", " << ans.second << "]";

    return 0;
}


