            C++

    #include <iostream>
#include <vector>
#include <climits>
#include <cmath>
using namespace std;

vector<int> findClosestPair(vector<int> &a, vector<int> &b, int x)
{
    int l = 0, r = b.size() - 1;
    int diff = INT_MAX;
    vector<int> result(2);

    // Two pointer traversal
    while (l < a.size() && r >= 0)
    {
        int sum = a[l] + b[r];
        int currDiff = abs(sum - x);

        // Update result if better pair found
        if (currDiff < diff)
        {
            diff = currDiff;
            result[0] = a[l];
            result[1] = b[r];
        }

        // Move pointers
        if (sum > x)
            r--;
        else
            l++;
    }

    return result;
}

int main()
{
    vector<int> a = {1, 4, 5, 7};
    vector<int> b = {10, 20, 30, 40};
    int x = 38;

    vector<int> closest = findClosestPair(a, b, x);

    cout << "[" << closest[0] << ", " << closest[1] << "]";
    return 0;
}


