// Function to find the closest pair
void findClosestPair(int a[], int n, int b[], int m, int x) {
    int l = 0, r = m - 1;
    int diff = INT_MAX;
    int res1 = 0, res2 = 0;

    // Two pointer traversal
    while (l < n && r >= 0) {
        int sum = a[l] + b[r];
        int currDiff = abs(sum - x);

        // Update result if better pair found
        if (currDiff < diff) {
            diff = currDiff;
            res1 = a[l];
            res2 = b[r];
        }

        // Move pointers
        if (sum > x)
            r--;
        else
            l++;
    }

    printf("[%d, %d]", res1, res2);
}

